const ARTICLES=[{id:"article-1",url:"https://tiepthigiadinh.vn/tin-anh-soi-noi-giai-mini-pickleball-thu-do-2026-lan-toa-tinh-than-doan-ket-trong-cong-dong-doanh-nghiep-quang-cao-d33676.html",title:"Sôi nổi Giải Mini Pickleball Thủ đô 2026, lan tỏa tinh thần đoàn kết trong cộng đồng doanh nghiệp quảng cáo",image:"https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782808228760_2051900956284874138_g2226604429797879813_f16c920194695a0a2fdc9c89796178d1-161311.webp",description:"Giải Mini Pickleball Thủ đô 2026 do Chi hội Quảng cáo Thủ đô tổ chức đã diễn ra sôi nổi với sự tham gia của đông đảo hội viên, doanh nghiệp quảng cáo.",content:'<article class="entry entry-no-padding">\n                                    <div class="sc-longform-header sc-longform-header-default-normal block-sc-longform-header">\n                                        <div class="sc-longform-header-text">\n                                            <span class="sc-longform-header-cate block-sc-cate-name">VAA</span>\n                                            <h1 class="sc-longform-header-title block-sc-title">\n                                                Sôi nổi Giải Mini Pickleball Thủ đô 2026, lan tỏa tinh thần đoàn kết trong cộng đồng doanh nghiệp quảng cáo                                                                                            </h1>\n                                            <div class="sc-longform-header-meta">\n                                                <span class="sc-longform-header-author block-sc-author">Hồng Phúc </span> <span class="sc-text block-sc-text">•</span>\n                                                <span class="sc-longform-header-date block-sc-publish-time">Thứ ba, 30/06/2026, 17:27 (GMT+7)</span>\n                                            </div>\n                                            <p class="sc-longform-header-sapo block-sc-sapo">Chiều 30/6, tại sân DK (Khu đô thị Đại Kim, Hà Nội), Giải Mini Pickleball Thủ đô 2026 do Chi hội Quảng cáo Thủ đô tổ chức đã diễn ra sôi nổi với sự tham gia của đông đảo hội viên, doanh nghiệp trong ngành quảng cáo, truyền thông cùng các câu lạc bộ khách mời.</p>\n                                        </div>\n                                    </div>\n                                    <div class="c-article-relation article_relation">\n                                                                                    <p class="sc-relation">\n                                                <a href="https://tiepthigiadinh.vn/sap-dien-ra-giai-mini-pickleball-va-ra-mat-cau-lac-bo-pickleball-cua-nganh-quang-cao-d33460.html" class="" title="Sắp diễn ra Giải Mini Pickleball và ra mắt Câu lạc bộ Pickleball của quảng cáo Thủ đô">Sắp diễn ra Giải Mini Pickleball và ra mắt Câu lạc bộ Pickleball của quảng cáo Thủ đô</a>                                            </p>\n                                                                                    <p class="sc-relation">\n                                                <a href="https://tiepthigiadinh.vn/chi-hoi-quang-cao-thu-do-to-chuc-dai-hoi-lan-thu-ii-nhiem-ky-2026--2028-d31355.html" class="" title="Chi hội Quảng cáo Thủ đô tổ chức Đại hội lần thứ II, nhiệm kỳ 2026 - 2028">Chi hội Quảng cáo Thủ đô tổ chức Đại hội lần thứ II, nhiệm kỳ 2026 - 2028</a>                                            </p>\n                                                                                    <p class="sc-relation">\n                                                <a href="https://tiepthigiadinh.vn/sap-dien-ra-dai-hoi-chi-hoi-quang-cao-thu-do-lan-ii-va-giai-pickleball-mo-rong-2026-d31170.html" class="" title="Sắp diễn ra Đại hội Chi hội Quảng cáo Thủ đô lần II và Giải Pickleball mở rộng 2026">Sắp diễn ra Đại hội Chi hội Quảng cáo Thủ đô lần II và Giải Pickleball mở rộng 2026</a>                                            </p>\n                                                                            </div>\n                                    <div class="detail-content afcbc-body detail-page" id="content_detail">\n                                        <p style="text-align: justify;">Giải đấu nằm trong chuỗi hoạt động chào mừng Lễ ra mắt Câu lạc bộ Pickleball CAA và kết nạp hội viên mới của <a href="https://tiepthigiadinh.vn/sap-dien-ra-giai-mini-pickleball-va-ra-mat-cau-lac-bo-pickleball-cua-nganh-quang-cao-d33460.html">Chi hội Quảng cáo Thủ đô,</a> hướng tới mục tiêu tăng cường phong trào rèn luyện thể thao, nâng cao sức khỏe, đồng thời tạo môi trường giao lưu, kết nối giữa các doanh nghiệp.</p>  <p style="text-align: justify;">Tham gia giải có các vận động viên đến từ Chi hội Quảng cáo Thủ đô cùng các câu lạc bộ khách mời như CLB Pickleball Yên Xá, CLB Pickleball Sao Băng và CLB Pickleball Led Hà Nội... Các cặp vận động viên tranh tài ở bốn bảng đấu trước khi bước vào các vòng tứ kết, bán kết và chung kết.</p>  <p style="text-align: justify;">Với tinh thần "giao lưu là chính", các trận đấu diễn ra trong không khí hào hứng, cởi mở nhưng không kém phần hấp dẫn. Những pha bóng đẹp mắt, các tình huống phối hợp ăn ý cùng sự cổ vũ nhiệt tình của các cổ động viên đã tạo nên bầu không khí sôi động trên sân đấu.</p>  <p style="text-align: justify;">Theo Ban Tổ chức, mục tiêu lớn nhất của giải không chỉ là tìm ra những cặp vận động viên xuất sắc mà còn góp phần xây dựng sân chơi lành mạnh, tăng cường sự đoàn kết, kết nối và mở rộng cơ hội hợp tác giữa các doanh nghiệp trong cộng đồng quảng cáo Thủ đô.</p>  <p style="text-align: justify;"><em><strong>Một số hình ảnh tại Giải Mini Pickleball Thủ đô 2026:</strong></em></p>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782800590984_2667936099012619237_g2226604429797879813_5c3dca8ee264837dea72f5404e54dc9b-162525.webp" rel="nofollow noopener" data-caption="Toàn cảnh không khí thi đấu sôi nổi tại sân DK, nơi quy tụ các vận động viên là hội viên Chi hội Quảng cáo Thủ đô và các câu lạc bộ khách mời.">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782800590984_2667936099012619237_g2226604429797879813_5c3dca8ee264837dea72f5404e54dc9b-162525.webp" alt="1782800590984_2667936099012619237_g2226604429797879813_5c3dca8ee264837dea72f5404e54dc9b-1625" title="Toàn cảnh không khí thi đấu sôi nổi tại sân DK, nơi quy tụ các vận động viên là hội viên Chi hội Quảng cáo Thủ đô và các câu lạc bộ khách mời." width="2560" height="1182" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Toàn cảnh không khí thi đấu sôi nổi tại sân DK, nơi quy tụ các vận động viên là hội viên Chi hội Quảng cáo Thủ đô và các câu lạc bộ khách mời.</em></figcaption>  </figure>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782808228750_2051900956284874138_g2226604429797879813_f63ad1c17de4a56abcb185149bf6b15b-161254.webp" rel="nofollow noopener" data-caption="Các cặp vận động viên được chia thành 4 bảng đấu (A, B, C và D), thi đấu vòng bảng để lựa chọn những đội xuất sắc bước vào các vòng tứ kết, bán kết và chung kết.">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782808228750_2051900956284874138_g2226604429797879813_f63ad1c17de4a56abcb185149bf6b15b-161254.webp" alt="1782808228750_2051900956284874138_g2226604429797879813_f63ad1c17de4a56abcb185149bf6b15b-1612" title="Các cặp vận động viên được chia thành 4 bảng đấu (A, B, C và D), thi đấu vòng bảng để lựa chọn những đội xuất sắc bước vào các vòng tứ kết, bán kết và chung kết." width="2560" height="1707" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Các cặp vận động viên được chia thành 4 bảng đấu (A, B, C và D), thi đấu vòng bảng để lựa chọn những đội xuất sắc bước vào các vòng tứ kết, bán kết và chung kết.</em></figcaption>  </figure>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782808228748_2051900956284874138_g2226604429797879813_509245df36e67dd6178dfbe1cdba8b04-161552.webp" rel="nofollow noopener" data-caption="Trọng tài phổ biến và điều hành trận đấu giữa các cặp vận động viên ngay từ những lượt thi đấu đầu tiên của vòng bảng.">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782808228748_2051900956284874138_g2226604429797879813_509245df36e67dd6178dfbe1cdba8b04-161552.webp" alt="1782808228748_2051900956284874138_g2226604429797879813_509245df36e67dd6178dfbe1cdba8b04-1615" title="Trọng tài phổ biến và điều hành trận đấu giữa các cặp vận động viên ngay từ những lượt thi đấu đầu tiên của vòng bảng." width="2560" height="1707" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Trọng tài phổ biến và điều hành trận đấu giữa các cặp vận động viên ngay từ những lượt thi đấu đầu tiên của vòng bảng.</em></figcaption>  </figure>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782808228760_2051900956284874138_g2226604429797879813_f16c920194695a0a2fdc9c89796178d1-161311.webp" rel="nofollow noopener" data-caption="Các cặp vận động viên ở các bảng đấu thi đấu quyết tâm, thể hiện tinh thần thể thao, đoàn kết và fair-play.">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782808228760_2051900956284874138_g2226604429797879813_f16c920194695a0a2fdc9c89796178d1-161311.webp" alt="1782808228760_2051900956284874138_g2226604429797879813_f16c920194695a0a2fdc9c89796178d1-1613" title="Các cặp vận động viên ở các bảng đấu thi đấu quyết tâm, thể hiện tinh thần thể thao, đoàn kết và fair-play." width="2560" height="1707" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Các cặp vận động viên ở các bảng đấu thi đấu quyết tâm, thể hiện tinh thần thể thao, đoàn kết và fair-play.</em></figcaption>  </figure>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782808228790_2051900956284874138_g2226604429797879813_1eb23e2890f959b079e9de914811643a-161634.webp" rel="nofollow noopener" data-caption="Những pha điều bóng chính xác cùng sự phối hợp ăn ý tạo nên nhiều màn so tài hấp dẫn trên sân.">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782808228790_2051900956284874138_g2226604429797879813_1eb23e2890f959b079e9de914811643a-161634.webp" alt="1782808228790_2051900956284874138_g2226604429797879813_1eb23e2890f959b079e9de914811643a-1616" title="Những pha điều bóng chính xác cùng sự phối hợp ăn ý tạo nên nhiều màn so tài hấp dẫn trên sân." width="2560" height="1707" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Những pha điều bóng chính xác cùng sự phối hợp ăn ý tạo nên nhiều màn so tài hấp dẫn trên sân.</em></figcaption>  </figure>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782836602764_2716064877784046674_2716064877784046674_d37177d203886c6571c9a56f0b125e65-233028.webp" rel="nofollow noopener" data-caption="Các vận động viên thi đấu quyết tâm trong từng pha bóng, cống hiến nhiều tình huống giằng co kịch tính.">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782836602764_2716064877784046674_2716064877784046674_d37177d203886c6571c9a56f0b125e65-233028.webp" alt="1782836602764_2716064877784046674_2716064877784046674_d37177d203886c6571c9a56f0b125e65-2330" title="Các vận động viên thi đấu quyết tâm trong từng pha bóng, cống hiến nhiều tình huống giằng co kịch tính." width="2560" height="1707" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Các vận động viên thi đấu quyết tâm trong từng pha bóng, cống hiến nhiều tình huống giằng co kịch tính.</em></figcaption>  </figure>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782808228782_2051900956284874138_g2226604429797879813_467db285de57bd2fdeab24ba73172f2a-161321.webp" rel="nofollow noopener" data-caption="Dù thi đấu cạnh tranh, các vận động viên vẫn đề cao tinh thần giao lưu, học hỏi và kết nối giữa các doanh nghiệp.">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782808228782_2051900956284874138_g2226604429797879813_467db285de57bd2fdeab24ba73172f2a-161321.webp" alt="1782808228782_2051900956284874138_g2226604429797879813_467db285de57bd2fdeab24ba73172f2a-1613" title="Dù thi đấu cạnh tranh, các vận động viên vẫn đề cao tinh thần giao lưu, học hỏi và kết nối giữa các doanh nghiệp." width="2560" height="1707" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Dù thi đấu cạnh tranh, các vận động viên vẫn đề cao tinh thần giao lưu, học hỏi và kết nối giữa các doanh nghiệp.</em></figcaption>  </figure>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782808228796_2051900956284874138_g2226604429797879813_5a9a8242b3449b9da3b86d49914742a9-161612.webp" rel="nofollow noopener" data-caption="Giải Mini Pickleball Thủ đô 2026 là dịp để các doanh nghiệp trong ngành quảng cáo tăng cường giao lưu, mở rộng kết nối và lan tỏa phong trào rèn luyện thể thao.">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/06/30/1782808228796_2051900956284874138_g2226604429797879813_5a9a8242b3449b9da3b86d49914742a9-161612.webp" alt="1782808228796_2051900956284874138_g2226604429797879813_5a9a8242b3449b9da3b86d49914742a9-1616" title="Giải Mini Pickleball Thủ đô 2026 là dịp để các doanh nghiệp trong ngành quảng cáo tăng cường giao lưu, mở rộng kết nối và lan tỏa phong trào rèn luyện thể thao." width="2560" height="1707" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Giải Mini Pickleball Thủ đô 2026 là dịp để các doanh nghiệp trong ngành quảng cáo tăng cường giao lưu, mở rộng kết nối và lan tỏa phong trào rèn luyện thể thao.</em></figcaption>  </figure>                                    </div>\n                                    <div class="sc-empty-layer"></div>\n                                </article>'},{id:"article-2",url:"https://tiepthigiadinh.vn/sap-dien-ra-dai-hoi-chi-hoi-quang-cao-thu-do-lan-ii-va-giai-pickleball-mo-rong-2026-d31170.html",title:"Sắp diễn ra Đại hội Chi hội Quảng cáo Thủ đô lần II và Giải Pickleball mở rộng 2026",image:"https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/19/z7636566769328_809a354a1660b94c2b444fdbca935a6d-153523.webp",description:"Đại hội Chi hội Quảng cáo Thủ Đô lần thứ II (nhiệm kỳ 2026 - 2028) sẽ diễn ra vào ngày 28/3/2026, tại Hà Nội. Cùng ngày, Giải Pickleball Chi hội Quảng cáo Thủ đô",content:'<article class="entry entry-no-padding">\n                                    <div class="sc-longform-header sc-longform-header-default-normal block-sc-longform-header">\n                                        <div class="sc-longform-header-text">\n                                            <span class="sc-longform-header-cate block-sc-cate-name">VAA</span>\n                                            <h1 class="sc-longform-header-title block-sc-title">\n                                                Sắp diễn ra Đại hội Chi hội Quảng cáo Thủ đô lần II và Giải Pickleball mở rộng 2026                                                                                            </h1>\n                                            <div class="sc-longform-header-meta">\n                                                <span class="sc-longform-header-author block-sc-author">Hồng Phúc</span> <span class="sc-text block-sc-text">•</span>\n                                                <span class="sc-longform-header-date block-sc-publish-time">Thứ năm, 19/03/2026, 20:31 (GMT+7)</span>\n                                            </div>\n                                            <p class="sc-longform-header-sapo block-sc-sapo">Đại hội Chi hội Quảng cáo Thủ Đô lần thứ II (nhiệm kỳ 2026 - 2028) sẽ diễn ra vào ngày 28/3/2026, tại Hà Nội. Cùng ngày, Giải Pickleball Chi hội Quảng cáo Thủ đô lần thứ I mở rộng - 2026 cũng được tổ chức, hứa hẹn mang đến không khí sôi động, tăng cường giao lưu, kết nối giữa các hội viên trong toàn ngành.</p>\n                                        </div>\n                                    </div>\n                                    <div class="c-article-relation article_relation">\n                                                                                    <p class="sc-relation">\n                                                <a href="https://tiepthigiadinh.vn/chi-hoi-quang-cao-thu-do-dau-an-hanh-trinh-thien-nguyen-huong-ve-thai-nguyen--tuyen-quang-d28652.html" class="" title="Chi hội Quảng cáo Thủ đô: Dấu ấn hành trình thiện nguyện hướng về Thái Nguyên - Tuyên Quang">Chi hội Quảng cáo Thủ đô: Dấu ấn hành trình thiện nguyện hướng về Thái Nguyên - Tuyên Quang</a>                                            </p>\n                                                                                    <p class="sc-relation">\n                                                <a href="https://tiepthigiadinh.vn/chi-hoi-quang-cao-thu-do-keu-goi-ung-ho-dong-bao-vung-lu-thai-nguyen--tuyen-quang-d28418.html" class="" title="Chi hội Quảng cáo Thủ đô phát động ủng hộ đồng bào vùng lũ Thái Nguyên - Tuyên Quang">Chi hội Quảng cáo Thủ đô phát động ủng hộ đồng bào vùng lũ Thái Nguyên - Tuyên Quang</a>                                            </p>\n                                                                                    <p class="sc-relation">\n                                                <a href="https://tiepthigiadinh.vn/chi-hoi-quang-cao-thu-do-to-chuc-giao-luu-toa-dam-quan-tri-thue-thoi-ky-doi-moi-d27977.html" class="" title="Chi hội Quảng cáo Thủ đô tổ chức giao lưu, tọa đàm \'Quản trị thuế thời kỳ đổi mới\'">Chi hội Quảng cáo Thủ đô tổ chức giao lưu, tọa đàm \'Quản trị thuế thời kỳ đổi mới\'</a>                                            </p>\n                                                                            </div>\n                                    <div class="detail-content afcbc-body detail-page" id="content_detail">\n                                        <p style="text-align: justify;"><a href="https://tiepthigiadinh.vn/chi-hoi-quang-cao-thu-do-dau-an-hanh-trinh-thien-nguyen-huong-ve-thai-nguyen--tuyen-quang-d28652.html">Chi hội Quảng cáo Thủ Đô</a> (CAA – Capital Advertising Association) được thành lập theo Quyết định số 41/QĐ-BTV ngày 21/10/2022 của Hiệp hội Quảng cáo Việt Nam. Đây là tổ chức xã hội - nghề nghiệp đại diện cho cộng đồng doanh nghiệp hoạt động trong lĩnh vực quảng cáo với nhiều loại hình đa dạng, đóng vai trò cầu nối giữa các hội viên và cơ quan quản lý.</p>  <p style="text-align: justify;">Trong những năm qua, Chi hội Quảng cáo Thủ đô từng bước khẳng định vai trò trong việc bảo vệ quyền và lợi ích hợp pháp của hội viên, đồng thời thúc đẩy hợp tác, chia sẻ kinh nghiệm và nâng cao năng lực cạnh tranh trong bối cảnh ngành quảng cáo liên tục biến động và chuyển đổi.</p>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/19/z7636566769328_809a354a1660b94c2b444fdbca935a6d-153523.webp" rel="nofollow noopener" data-caption="Đại hội chi hội thành lập Chi hội Quảng cáo Thủ đô lần thứ I, nhiệm kỳ 2022 - 2025. ">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/19/z7636566769328_809a354a1660b94c2b444fdbca935a6d-153523.webp" alt="z7636566769328_809a354a1660b94c2b444fdbca935a6d-1535" title="Đại hội chi hội thành lập Chi hội Quảng cáo Thủ đô lần thứ I, nhiệm kỳ 2022 - 2025. " width="1000" height="667" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Đại hội chi hội thành lập Chi hội Quảng cáo Thủ đô lần thứ I, nhiệm kỳ 2022 - 2025. </em></figcaption>  </figure>  <p style="text-align: justify;">Đại hội lần thứ II là sự kiện quan trọng nhằm tổng kết hoạt động nhiệm kỳ 2022 - 2026, đồng thời đề ra phương hướng, chiến lược phát triển cho giai đoạn 2026 - 2028. Đại hội được kỳ vọng sẽ tiếp tục củng cố tinh thần đoàn kết, tăng cường sự gắn kết giữa các hội viên và định hướng phát triển phù hợp với xu thế mới của thị trường quảng cáo.</p>  <p style="text-align: justify;">Song song với Đại hội, “Giải Pickleball Chi hội Quảng cáo Thủ đô lần thứ I mở rộng - 2026” được tổ chức như một điểm nhấn đặc biệt, mang màu sắc trẻ trung và năng động. Giải đấu sẽ diễn ra tại Cụm sân Pickleball - Đại học Thăng Long (Hà Nội), quy tụ sự tham gia của các hội viên CAA và các đơn vị trực thuộc VAA trên toàn quốc.</p>  <p style="text-align: justify;">“Sự kiện nhằm mục đích rèn luyện sức khỏe, tăng cường giao lưu hội viên trong các Chi hội trực thuộc Hiệp hội Quảng cáo Việt Nam, đồng thời chào mừng Đại hội Chi hội Quảng cáo Thủ đô”, đại diện Ban Tổ chức cho biết.</p>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/19/thumb-1-155040.webp" rel="nofollow noopener" data-caption="Giải Pickleball Chi hội Quảng cáo Thủ đô lần thứ I mở rộng - 2026 sẽ diễn ra trong ngày 28/3. ">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/19/thumb-1-155040.webp" alt="thumb-1-1550" title="Giải Pickleball Chi hội Quảng cáo Thủ đô lần thứ I mở rộng - 2026 sẽ diễn ra trong ngày 28/3. " width="1920" height="1080" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Giải Pickleball Chi hội Quảng cáo Thủ đô lần thứ I mở rộng - 2026 sẽ diễn ra trong ngày 28/3. </em></figcaption>  </figure>  <p style="text-align: justify;">Theo Ban Tổ chức, giải đấu được chuẩn bị bài bản từ công tác tổ chức thi đấu, điều phối đến hậu cần nhằm đảm bảo tính chuyên nghiệp, công bằng và an toàn cho các vận động viên. Không chỉ là hoạt động thể thao, giải Pickleball còn được kỳ vọng trở thành sân chơi thường niên, góp phần xây dựng văn hóa kết nối trong cộng đồng doanh nghiệp quảng cáo.</p>  <p style="text-align: justify;">Bên cạnh đó, sự kiện cũng mở ra cơ hội để các hội viên gặp gỡ, trao đổi, tìm kiếm cơ hội hợp tác trong bối cảnh ngành quảng cáo đang bước vào giai đoạn chuyển đổi mạnh mẽ, đặc biệt dưới tác động của công nghệ và xu hướng truyền thông mới.</p>  <p style="text-align: justify;">Sự kết hợp giữa hoạt động chuyên môn và thể thao trong cùng một ngày được kỳ vọng sẽ tạo nên dấu ấn riêng cho cộng đồng quảng cáo Thủ đô, lan tỏa hình ảnh một ngành nghề năng động, sáng tạo và không ngừng đổi mới.</p>                                    </div>\n                                    <div class="sc-empty-layer"></div>\n                                </article>'},{id:"article-3",url:"https://tiepthigiadinh.vn/chi-hoi-quang-cao-thu-do-ket-nap-hoi-vien-moi-ra-mat-cau-lac-bo-pickleball-caa-d33694.html",title:"Chi hội Quảng cáo Thủ đô kết nạp hội viên mới, ra mắt Câu lạc bộ Pickleball CAA",image:"https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887992270_2051900956284874138_g2226604429797879813_37edd992113e55762b6c3efe767f4b85-135636.webp",description:"Tối 30/6, Chi hội Quảng cáo Thủ đô tổ chức Gala kết nạp hội viên mới, ra mắt Câu lạc bộ Pickleball CAA và trao giải Giải Mini Pickleball Thủ đô 2026.",content:'<article class="entry entry-no-padding">\n                                    <div class="sc-longform-header sc-longform-header-default-normal block-sc-longform-header">\n                                        <div class="sc-longform-header-text">\n                                            <span class="sc-longform-header-cate block-sc-cate-name">VAA</span>\n                                            <h1 class="sc-longform-header-title block-sc-title">\n                                                Chi hội Quảng cáo Thủ đô kết nạp hội viên mới, ra mắt Câu lạc bộ Pickleball CAA                                                                                            </h1>\n                                            <div class="sc-longform-header-meta">\n                                                <span class="sc-longform-header-author block-sc-author">Hồng Phúc </span> <span class="sc-text block-sc-text">•</span>\n                                                <span class="sc-longform-header-date block-sc-publish-time">Thứ tư, 01/07/2026, 14:38 (GMT+7)</span>\n                                            </div>\n                                            <p class="sc-longform-header-sapo block-sc-sapo">Tối 30/6, Chi hội Quảng cáo Thủ đô tổ chức Gala kết nạp hội viên mới, ra mắt Câu lạc bộ Pickleball CAA và trao giải Giải Mini Pickleball Thủ đô 2026. Sự kiện đánh dấu bước phát triển mới của Chi hội trong việc mở rộng mạng lưới hội viên, tăng cường kết nối doanh nghiệp và xây dựng các hoạt động cộng đồng hướng tới sự phát triển bền vững của ngành quảng cáo.</p>\n                                        </div>\n                                    </div>\n                                    <div class="c-article-relation article_relation">\n                                                                                    <p class="sc-relation">\n                                                <a href="https://tiepthigiadinh.vn/tin-anh-soi-noi-giai-mini-pickleball-thu-do-2026-lan-toa-tinh-than-doan-ket-trong-cong-dong-doanh-nghiep-quang-cao-d33676.html" class="" title="Sôi nổi Giải Mini Pickleball Thủ đô 2026, lan tỏa tinh thần đoàn kết trong cộng đồng doanh nghiệp quảng cáo">Sôi nổi Giải Mini Pickleball Thủ đô 2026, lan tỏa tinh thần đoàn kết trong cộng đồng doanh nghiệp quảng cáo</a>                                            </p>\n                                                                                    <p class="sc-relation">\n                                                <a href="https://tiepthigiadinh.vn/chi-hoi-quang-cao-thu-do-dau-an-hanh-trinh-thien-nguyen-huong-ve-thai-nguyen--tuyen-quang-d28652.html" class="" title="Chi hội Quảng cáo Thủ đô: Dấu ấn hành trình thiện nguyện hướng về Thái Nguyên - Tuyên Quang">Chi hội Quảng cáo Thủ đô: Dấu ấn hành trình thiện nguyện hướng về Thái Nguyên - Tuyên Quang</a>                                            </p>\n                                                                                    <p class="sc-relation">\n                                                <a href="https://tiepthigiadinh.vn/chi-hoi-quang-cao-thu-do-keu-goi-ung-ho-dong-bao-vung-lu-thai-nguyen--tuyen-quang-d28418.html" class="" title="Chi hội Quảng cáo Thủ đô phát động ủng hộ đồng bào vùng lũ Thái Nguyên - Tuyên Quang">Chi hội Quảng cáo Thủ đô phát động ủng hộ đồng bào vùng lũ Thái Nguyên - Tuyên Quang</a>                                            </p>\n                                                                            </div>\n                                    <div class="detail-content afcbc-body detail-page" id="content_detail">\n                                        <p style="text-align: justify;">Sau một ngày thi đấu sôi nổi của <a href="https://tiepthigiadinh.vn/tin-anh-soi-noi-giai-mini-pickleball-thu-do-2026-lan-toa-tinh-than-doan-ket-trong-cong-dong-doanh-nghiep-quang-cao-d33676.html">Giải Mini Pickleball Thủ đô 2026</a>, Gala kết nạp hội viên mới và ra mắt Câu lạc bộ Pickleball CAA diễn ra trong không khí trang trọng, ấm cúng với sự tham dự của lãnh đạo Chi hội Quảng cáo Thủ đô, đại diện các doanh nghiệp, đối tác, các câu lạc bộ khách mời cùng đông đảo hội viên.</p>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887854714_2051900956284874138_g2226604429797879813_466be7a832312a17714ab293356efe53-135244.webp" rel="nofollow noopener" data-caption="Ông Nguyễn Ích Huy Hoàng, Chủ tịch Chi hội Quảng cáo Thủ đô phát biểu tại sự kiện">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887854714_2051900956284874138_g2226604429797879813_466be7a832312a17714ab293356efe53-135244.webp" alt="1782887854714_2051900956284874138_g2226604429797879813_466be7a832312a17714ab293356efe53-1352" title="Ông Nguyễn Ích Huy Hoàng, Chủ tịch Chi hội Quảng cáo Thủ đô phát biểu tại sự kiện" width="2560" height="1707" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Ông Nguyễn Ích Huy Hoàng, Chủ tịch Chi hội Quảng cáo Thủ đô phát biểu tại sự kiện</em></figcaption>  </figure>  <p style="text-align: justify;">Phát biểu tại chương trình, ông Nguyễn Ích Huy Hoàng, Chủ tịch Chi hội Quảng cáo Thủ đô cho rằng, trong bối cảnh ngành quảng cáo đang không ngừng đổi mới, sự kết nối giữa các doanh nghiệp và những người hoạt động trong lĩnh vực quảng cáo ngày càng có ý nghĩa quan trọng.</p>  <p style="text-align: justify;">Theo đó, một tổ chức hội không chỉ là nơi tập hợp lực lượng mà còn phải trở thành môi trường để các hội viên chia sẻ kinh nghiệm, mở rộng cơ hội hợp tác và cùng nhau phát triển.</p>  <p style="text-align: justify;">"Việc Chi hội Quảng cáo Thủ đô tiếp tục kết nạp thêm các hội viên mới không chỉ là niềm vui của Ban Chấp hành mà còn là minh chứng cho sức hút, uy tín và tinh thần đoàn kết của Chi hội. Sự tham gia của các thành viên mới sẽ góp phần bổ sung nguồn lực, làm phong phú thêm ý tưởng và tạo ra nhiều giá trị thiết thực cho cộng đồng doanh nghiệp quảng cáo", ông Huy Hoàng nhấn mạnh. </p>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887854758_2051900956284874138_g2226604429797879813_3d3b24cc82f72128aef4a910333036ce-135405.webp" rel="nofollow noopener" data-caption="Đại diện Ban Chấp hành Chi hội Quảng cáo Thủ đô trao quyết định kết nạp hội viên mới.">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887854758_2051900956284874138_g2226604429797879813_3d3b24cc82f72128aef4a910333036ce-135405.webp" alt="1782887854758_2051900956284874138_g2226604429797879813_3d3b24cc82f72128aef4a910333036ce-1354" title="Đại diện Ban Chấp hành Chi hội Quảng cáo Thủ đô trao quyết định kết nạp hội viên mới." width="2560" height="1639" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Đại diện Ban Chấp hành Chi hội Quảng cáo Thủ đô trao quyết định kết nạp hội viên mới.</em></figcaption>  </figure>  <p style="text-align: justify;">Cũng tại sự kiện, ông Bùi Xuân Diện (Công ty Cổ phần Quảng cáo và Truyền thông DT Group) - đại diện các hội viên mới bày tỏ vinh dự khi chính thức trở thành thành viên của Chi hội Quảng cáo Thủ đô.</p>  <p style="text-align: justify;">Ông cho rằng việc tham gia Chi hội không chỉ mở ra cơ hội giao lưu, học hỏi và kết nối với các doanh nghiệp trong ngành mà còn là trách nhiệm để mỗi hội viên đóng góp vào sự phát triển chung của tổ chức.</p>  <p style="text-align: justify;">"Chúng tôi mong muốn được đồng hành cùng Chi hội, tích cực tham gia các hoạt động, đóng góp một phần giá trị và công sức để Chi hội Quảng cáo Thủ đô ngày càng phát triển, tạo thêm nhiều cơ hội hợp tác cho cộng đồng doanh nghiệp quảng cáo", ông Diện chia sẻ.</p>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887854781_2051900956284874138_g2226604429797879813_b5c25b93d1b59f866cd83b234713d38b-135345.webp" rel="nofollow noopener" data-caption="Ông Bùi Xuân Diện (Công ty Cổ phần Quảng cáo và Truyền thông DT Group) phát biểu tại sự kiện">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887854781_2051900956284874138_g2226604429797879813_b5c25b93d1b59f866cd83b234713d38b-135345.webp" alt="1782887854781_2051900956284874138_g2226604429797879813_b5c25b93d1b59f866cd83b234713d38b-1353" title="Ông Bùi Xuân Diện (Công ty Cổ phần Quảng cáo và Truyền thông DT Group) phát biểu tại sự kiện" width="2560" height="1707" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Ông Bùi Xuân Diện (Công ty Cổ phần Quảng cáo và Truyền thông DT Group) phát biểu tại sự kiện</em></figcaption>  </figure>  <p style="text-align: justify;">Bên cạnh việc mở rộng tổ chức, Chi hội cũng chính thức ra mắt Câu lạc bộ Pickleball CAA, một sân chơi thể thao dành cho các hội viên và doanh nghiệp trong ngành.</p>  <p style="text-align: justify;">Theo Chủ tịch Chi hội Quảng cáo Thủ đô, ngoài các hoạt động chuyên môn, Ban Chấp hành luôn mong muốn xây dựng Chi hội trở thành "mái nhà chung", nơi các hội viên không chỉ gặp gỡ trong công việc mà còn gắn kết thông qua các hoạt động văn hóa, thể thao và giao lưu.</p>  <p style="text-align: justify;">"Câu lạc bộ Pickleball CAA không chỉ là nơi rèn luyện sức khỏe mà còn là cầu nối để các doanh nghiệp tăng cường giao lưu, mở rộng quan hệ, xây dựng tình bạn và thúc đẩy các cơ hội hợp tác trong môi trường gần gũi, cởi mở", ông Nguyễn Ích Huy Hoàng chia sẻ.</p>  <p style="text-align: justify;">Ông bày tỏ kỳ vọng câu lạc bộ sẽ duy trì hoạt động thường xuyên, thu hút ngày càng nhiều hội viên tham gia, qua đó góp phần xây dựng cộng đồng doanh nghiệp quảng cáo đoàn kết, năng động và giàu sức sống.</p>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887855141_2051900956284874138_g2226604429797879813_41f2a7530d0b9ad5dab09cfa354dc140-135838.webp" rel="nofollow noopener" data-caption="">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887855141_2051900956284874138_g2226604429797879813_41f2a7530d0b9ad5dab09cfa354dc140-135838.webp" alt="1782887855141_2051900956284874138_g2226604429797879813_41f2a7530d0b9ad5dab09cfa354dc140-1358" title="" width="2560" height="1707" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"></figcaption>  </figure>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887855121_2051900956284874138_g2226604429797879813_eae3c42dfd3de97ac287cf743cc60047-135853.webp" rel="nofollow noopener" data-caption="">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887855121_2051900956284874138_g2226604429797879813_eae3c42dfd3de97ac287cf743cc60047-135853.webp" alt="1782887855121_2051900956284874138_g2226604429797879813_eae3c42dfd3de97ac287cf743cc60047-1358" title="" width="2560" height="1707" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"></figcaption>  </figure>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887855096_2051900956284874138_g2226604429797879813_11b4aef4cf2483420bb57d119abd987c-135819.webp" rel="nofollow noopener" data-caption="Ban Tổ chức trao giải cho các vận động viên đạt thành tích cao tại Giải Mini Pickleball Thủ đô 2026.">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887855096_2051900956284874138_g2226604429797879813_11b4aef4cf2483420bb57d119abd987c-135819.webp" alt="1782887855096_2051900956284874138_g2226604429797879813_11b4aef4cf2483420bb57d119abd987c-1358" title="Ban Tổ chức trao giải cho các vận động viên đạt thành tích cao tại Giải Mini Pickleball Thủ đô 2026." width="2560" height="1707" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Ban Tổ chức trao giải cho các vận động viên đạt thành tích cao tại Giải Mini Pickleball Thủ đô 2026.</em></figcaption>  </figure>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887992270_2051900956284874138_g2226604429797879813_37edd992113e55762b6c3efe767f4b85-135636.webp" rel="nofollow noopener" data-caption="CAA kỳ vọng môi trường kết nối toàn diện giữa các doanh nghiệp thông qua đa dạng các hoạt động.">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/07/01/1782887992270_2051900956284874138_g2226604429797879813_37edd992113e55762b6c3efe767f4b85-135636.webp" alt="1782887992270_2051900956284874138_g2226604429797879813_37edd992113e55762b6c3efe767f4b85-1356" title="CAA kỳ vọng môi trường kết nối toàn diện giữa các doanh nghiệp thông qua đa dạng các hoạt động." width="2560" height="1507" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>CAA kỳ vọng môi trường kết nối toàn diện giữa các doanh nghiệp thông qua đa dạng các hoạt động.</em></figcaption>  </figure>  <p style="text-align: justify;">Trong khuôn khổ đêm Gala, Ban Tổ chức cũng trao giải cho các vận động viên đạt thành tích cao tại Giải Mini Pickleball Thủ đô 2026. Trước đó, giải đấu diễn ra với sự tham gia của các hội viên Chi hội Quảng cáo Thủ đô và các câu lạc bộ khách mời, mang đến nhiều trận đấu hấp dẫn trên tinh thần giao lưu, đoàn kết và fair-play.</p>  <p style="text-align: justify;">Việc kết hợp tổ chức giải thể thao, kết nạp hội viên mới và ra mắt Câu lạc bộ Pickleball CAA tiếp tục khẳng định định hướng của Chi hội Quảng cáo Thủ đô trong việc đa dạng hóa hoạt động, xây dựng môi trường kết nối toàn diện giữa các doanh nghiệp.</p>  <p style="text-align: justify;">Qua đó, Chi hội hướng tới mục tiêu trở thành điểm kết nối tin cậy, góp phần thúc đẩy sự phát triển của cộng đồng doanh nghiệp quảng cáo Thủ đô theo hướng chuyên nghiệp, sáng tạo và bền vững.</p>                                    </div>\n                                    <div class="sc-empty-layer"></div>\n                                </article>'},{id:"article-4",url:"https://tiepthigiadinh.vn/chi-hoi-quang-cao-thu-do-to-chuc-dai-hoi-lan-thu-ii-nhiem-ky-2026--2028-d31355.html",title:"Chi hội Quảng cáo Thủ đô tổ chức Đại hội lần thứ II, nhiệm kỳ 2026 - 2028",image:"https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/29/thumb-1-002737.webp",description:"Ngày 28/3, tại Hà Nội, Chi hội Quảng cáo Thủ đô tổ chức Đại hội lần thứ II, nhiệm kỳ 2026 – 2028. Sự kiện có sự tham dự của nhà báo, đạo diễn Nguyễn Trường Sơn - Chủ tịch Hiệp hội Quảng Cáo Việt Nam, lãnh đạo ngành quảng cáo cùng đông đảo hội viên Chi hội Quảng cáo Thủ đô.",content:'<article class="entry entry-no-padding">\n                                    <div class="sc-longform-header sc-longform-header-default-normal block-sc-longform-header">\n                                        <div class="sc-longform-header-text">\n                                            <span class="sc-longform-header-cate block-sc-cate-name">VAA</span>\n                                            <h1 class="sc-longform-header-title block-sc-title">\n                                                Chi hội Quảng cáo Thủ đô tổ chức Đại hội lần thứ II, nhiệm kỳ 2026 - 2028                                                                                            </h1>\n                                            <div class="sc-longform-header-meta">\n                                                <span class="sc-longform-header-author block-sc-author">Hồng Phúc - Việt Đức</span> <span class="sc-text block-sc-text">•</span>\n                                                <span class="sc-longform-header-date block-sc-publish-time">Chủ nhật, 29/03/2026, 07:31 (GMT+7)</span>\n                                            </div>\n                                            <p class="sc-longform-header-sapo block-sc-sapo">Ngày 28/3, tại Hà Nội, Chi hội Quảng cáo Thủ đô tổ chức Đại hội lần thứ II, nhiệm kỳ 2026 – 2028. Sự kiện có sự tham dự của nhà báo, đạo diễn Nguyễn Trường Sơn - Chủ tịch Hiệp hội Quảng Cáo Việt Nam, lãnh đạo ngành quảng cáo cùng đông đảo hội viên Chi hội Quảng cáo Thủ đô.</p>\n                                        </div>\n                                    </div>\n                                    <div class="c-article-relation article_relation">\n                                                                                    <p class="sc-relation">\n                                                <a href="https://tiepthigiadinh.vn/sap-dien-ra-dai-hoi-chi-hoi-quang-cao-thu-do-lan-ii-va-giai-pickleball-mo-rong-2026-d31170.html" class="" title="Sắp diễn ra Đại hội Chi hội Quảng cáo Thủ đô lần II và Giải Pickleball mở rộng 2026">Sắp diễn ra Đại hội Chi hội Quảng cáo Thủ đô lần II và Giải Pickleball mở rộng 2026</a>                                            </p>\n                                                                                    <p class="sc-relation">\n                                                <a href="https://tiepthigiadinh.vn/chi-hoi-quang-cao-thu-do-dau-an-hanh-trinh-thien-nguyen-huong-ve-thai-nguyen--tuyen-quang-d28652.html" class="" title="Chi hội Quảng cáo Thủ đô: Dấu ấn hành trình thiện nguyện hướng về Thái Nguyên - Tuyên Quang">Chi hội Quảng cáo Thủ đô: Dấu ấn hành trình thiện nguyện hướng về Thái Nguyên - Tuyên Quang</a>                                            </p>\n                                                                                    <p class="sc-relation">\n                                                <a href="https://tiepthigiadinh.vn/chi-hoi-quang-cao-thu-do-to-chuc-giao-luu-toa-dam-quan-tri-thue-thoi-ky-doi-moi-d27977.html" class="" title="Chi hội Quảng cáo Thủ đô tổ chức giao lưu, tọa đàm \'Quản trị thuế thời kỳ đổi mới\'">Chi hội Quảng cáo Thủ đô tổ chức giao lưu, tọa đàm \'Quản trị thuế thời kỳ đổi mới\'</a>                                            </p>\n                                                                            </div>\n                                    <div class="detail-content afcbc-body detail-page" id="content_detail">\n                                        <p style="text-align: justify;"><a href="https://tiepthigiadinh.vn/sap-dien-ra-dai-hoi-chi-hoi-quang-cao-thu-do-lan-ii-va-giai-pickleball-mo-rong-2026-d31170.html">Chi hội Quảng cáo Thủ Đô</a> (CAA – Capital Advertising Association) được thành lập theo Quyết định số 41/QĐ-BTV ngày 21/10/2022 của Hiệp hội Quảng cáo Việt Nam.</p>  <p style="text-align: justify;">Trong những năm qua, Chi hội Quảng cáo Thủ đô từng bước khẳng định vai trò trong việc bảo vệ quyền và lợi ích hợp pháp của hội viên, đồng thời thúc đẩy hợp tác, chia sẻ kinh nghiệm và nâng cao năng lực cạnh tranh trong bối cảnh ngành quảng cáo liên tục biến động và chuyển đổi.</p>  <p style="text-align: justify;">Đại hội lần thứ II không chỉ tổng kết chặng đường 3 năm vừa qua mà còn đặt ra định hướng phát triển cho giai đoạn mới, trong bối cảnh ngành quảng cáo đang chuyển mình mạnh mẽ trước làn sóng công nghệ và chuyển đổi số.</p>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/29/z7668457778574_e81ba0a90faf83a5f58878d5a2343f34-002231.webp" rel="nofollow noopener" data-caption="Nhà báo, đạo diễn Nguyễn Trường Sơn - Chủ tịch Hiệp hội Quảng Cáo Việt Nam">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/29/z7668457778574_e81ba0a90faf83a5f58878d5a2343f34-002231.webp" alt="z7668457778574_e81ba0a90faf83a5f58878d5a2343f34-0022" title="Nhà báo, đạo diễn Nguyễn Trường Sơn - Chủ tịch Hiệp hội Quảng Cáo Việt Nam" width="1130" height="753" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Nhà báo, đạo diễn Nguyễn Trường Sơn - Chủ tịch Hiệp hội Quảng Cáo Việt Nam</em></figcaption>  </figure>  <p style="text-align: justify;">"Trong bối cảnh ngành quảng cáo đang chuyển dịch mạnh mẽ, Chi hội Quảng cáo Thủ đô cần tiếp tục phát huy vai trò kết nối, nâng cao hiệu quả hoạt động và chủ động thích ứng với xu thế công nghệ, chuyển đổi số, qua đó tạo nền tảng cho sự phát triển bền vững của cộng đồng doanh nghiệp", Chủ tịch Hiệp hội Quảng cáo Việt Nam Nguyễn Trường Sơn nhấn mạnh. </p>  <h2 data-start="1248" data-end="1316">Khẳng định vai trò, tăng cường kết nối hội viên</h2>  <p style="text-align: justify;">Phát biểu tại sự kiện, ông Nguyễn Ích Huy Hoàng - Chủ tịch Liên chi hội Quảng cáo Thủ đô cho biết, sau 3 năm hình thành và phát triển, Chi hội Quảng cáo Thủ đô đã từng bước khẳng định vai trò là một “ngôi nhà chung” của cộng đồng doanh nghiệp quảng cáo trên địa bàn.</p>  <p style="text-align: justify;">Từ những ngày đầu còn nhiều khó khăn, Chi hội đã có sự phát triển đáng ghi nhận cả về quy mô lẫn chất lượng hoạt động. Các chương trình kết nối, đặc biệt là chuỗi Caravan Hà Nội, đã trở thành điểm nhấn, không chỉ tạo không gian giao lưu mà còn mở ra cơ hội hợp tác, liên kết chiến lược giữa các hội viên.</p>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/29/z7668456650219_6accb10e04ee85b17935bda56058a5de-002321.webp" rel="nofollow noopener" data-caption="Nguyễn Ích Huy Hoàng - Chủ tịch Liên chi hội Quảng cáo Thủ đô">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/29/z7668456650219_6accb10e04ee85b17935bda56058a5de-002321.webp" alt="z7668456650219_6accb10e04ee85b17935bda56058a5de-0023" title="Nguyễn Ích Huy Hoàng - Chủ tịch Liên chi hội Quảng cáo Thủ đô" width="1288" height="859" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Nguyễn Ích Huy Hoàng - Chủ tịch Liên chi hội Quảng cáo Thủ đô</em></figcaption>  </figure>  <p style="text-align: justify;">“Chúng tôi xác định tinh thần ‘không đứng yên - cùng nhau chuyển động’ là nền tảng để nâng cao năng lực cạnh tranh, qua đó góp phần khẳng định vị thế của quảng cáo Thủ đô trong bức tranh chung của ngành”, ông Hoàng nhấn mạnh.</p>  <p style="text-align: justify;">Bên cạnh hoạt động chuyên môn, Chi hội cũng tích cực triển khai các chương trình trách nhiệm xã hội tại nhiều địa phương như Thái Nguyên, Tuyên Quang.</p>  <p style="text-align: justify;">Những hoạt động hỗ trợ kịp thời không chỉ mang ý nghĩa vật chất mà còn lan tỏa tinh thần trách nhiệm cộng đồng, thể hiện hình ảnh doanh nhân quảng cáo năng động và nhân văn.</p>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/29/z7668456645750_7b3249845dc47a6582675e2cda899454-002427.webp" rel="nofollow noopener" data-caption="Ra mắt BCH Chi hội Quảng cáo Thủ đô, nhiệm kỳ 2026 - 2028">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/29/z7668456645750_7b3249845dc47a6582675e2cda899454-002427.webp" alt="z7668456645750_7b3249845dc47a6582675e2cda899454-0024" title="Ra mắt BCH Chi hội Quảng cáo Thủ đô, nhiệm kỳ 2026 - 2028" width="1280" height="854" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Ra mắt BCH Chi hội Quảng cáo Thủ đô, nhiệm kỳ 2026 - 2028</em></figcaption>  </figure>  <p style="text-align: justify;">Tuy nhiên, lãnh đạo Chi hội cũng thẳng thắn nhìn nhận những hạn chế cần khắc phục. Trong đó, mức độ gắn kết giữa các hội viên chưa thực sự đồng đều; việc chuyển hóa các mối quan hệ kết nối thành hợp tác kinh tế cụ thể còn hạn chế; đặc biệt, việc ứng dụng công nghệ mới như trí tuệ nhân tạo (AI) và chuyển đổi số vẫn chưa theo kịp yêu cầu thực tiễn.</p>  <p style="text-align: justify;">“Chính những hạn chế này sẽ là động lực để Ban Chấp hành nhiệm kỳ tới đổi mới mạnh mẽ hơn, hướng tới những bước phát triển thực chất và bền vững”, ông Hoàng cho biết.</p>  <h2 style="text-align: justify;">Đổi mới tổ chức, thúc đẩy chuyển đổi số</h2>  <p style="text-align: justify;">Bước sang nhiệm kỳ 2026 - 2028, Chi hội Quảng cáo Thủ đô xác định phương châm hành động “Vững vàng - Sáng tạo - Đoàn kết - Vươn tầm”, tập trung vào ba trụ cột chiến lược gồm: kiện toàn tổ chức theo hướng chuyên nghiệp, minh bạch; đổi mới hoạt động, xây dựng hệ sinh thái kết nối đa chiều; và thúc đẩy ứng dụng công nghệ, đặc biệt là AI trong hoạt động quảng cáo.</p>  <p style="text-align: justify;">Trong khuôn khổ Đại hội, Chi hội Quảng cáo Thủ đô đã ra mắt Ban Chấp hành nhiệm kỳ 2026 - 2028, đánh dấu bước chuyển giao quan trọng trong công tác tổ chức và điều hành. </p>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/29/z7668456641658_4bee02e857269180008e81714700b851-002533.webp" rel="nofollow noopener" data-caption="Bà Trần Thị Thanh Trà - Chủ tịch danh dự Chi hội Quảng cáo Thủ đô cũng gửi gắm kỳ vọng tới đội ngũ kế nhiệm">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/29/z7668456641658_4bee02e857269180008e81714700b851-002533.webp" alt="z7668456641658_4bee02e857269180008e81714700b851-0025" title="Bà Trần Thị Thanh Trà - Chủ tịch danh dự Chi hội Quảng cáo Thủ đô cũng gửi gắm kỳ vọng tới đội ngũ kế nhiệm" width="1280" height="854" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Bà Trần Thị Thanh Trà - Chủ tịch danh dự Chi hội Quảng cáo Thủ đô cũng gửi gắm kỳ vọng tới đội ngũ kế nhiệm</em></figcaption>  </figure>  <p style="text-align: justify;">Dịp này, bà Trần Thị Thanh Trà - Chủ tịch danh dự Chi hội Quảng cáo Thủ đô cũng gửi gắm kỳ vọng tới đội ngũ kế nhiệm, mong muốn tiếp tục phát huy tinh thần đoàn kết, đổi mới và nâng cao hiệu quả hoạt động trong giai đoạn tới.</p>  <p style="text-align: justify;">Đáng chú ý, tại Đại hội cũng diễn ra lễ ra mắt Câu lạc bộ Thiện nguyện Khởi nghiệp trực thuộc Chi hội, do bà Trần Thanh Hương làm Chủ nhiệm.</p>  <p style="text-align: justify;">Việc thành lập câu lạc bộ được kỳ vọng sẽ góp phần lan tỏa các hoạt động vì cộng đồng, đồng thời hỗ trợ, kết nối các cá nhân, doanh nghiệp khởi nghiệp trong lĩnh vực quảng cáo và truyền thông.</p>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/29/z7668456643574_dd709d2dc68e40a32036535c25814e91-002604.webp" rel="nofollow noopener" data-caption="Lễ ra mắt Câu lạc bộ Thiện nguyện Khởi nghiệp trực thuộc Chi hội">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/29/z7668456643574_dd709d2dc68e40a32036535c25814e91-002604.webp" alt="z7668456643574_dd709d2dc68e40a32036535c25814e91-0026" title="Lễ ra mắt Câu lạc bộ Thiện nguyện Khởi nghiệp trực thuộc Chi hội" width="1280" height="854" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Lễ ra mắt Câu lạc bộ Thiện nguyện Khởi nghiệp trực thuộc Chi hội</em></figcaption>  </figure>  <figure class="cmxNonEdit">\r\n                <a href="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/29/z7668456649388_dbfb1ca2cb224a7cbb470146d452b366-002645.webp" rel="nofollow noopener" data-caption="Hiệp hội Quảng cáo Việt Nam đã tổ chức vinh danh các tập thể, cá nhân có đóng góp xuất sắc">\r\n                    <img src="https://t.cmx-cdn.com/tiepthigiadinh.vn/files/storage/2026/03/29/z7668456649388_dbfb1ca2cb224a7cbb470146d452b366-002645.webp" alt="z7668456649388_dbfb1ca2cb224a7cbb470146d452b366-0026" title="Hiệp hội Quảng cáo Việt Nam đã tổ chức vinh danh các tập thể, cá nhân có đóng góp xuất sắc" width="1280" height="854" loading="lazy" />\r\n                </a>  <figcaption class="cmxEdit"><em>Hiệp hội Quảng cáo Việt Nam đã tổ chức vinh danh các tập thể, cá nhân có đóng góp xuất sắc</em></figcaption>      </figure>  <p style="text-align: justify;">Cũng tại sự kiện, Hiệp hội Quảng cáo Việt Nam đã tổ chức vinh danh các tập thể, cá nhân có đóng góp xuất sắc, ghi nhận những nỗ lực và cống hiến của cộng đồng doanh nghiệp quảng cáo trong thời gian qua.</p>  <p style="text-align: justify;">Với định hướng rõ ràng cùng sự đồng thuận của hội viên, Đại hội lần thứ II được kỳ vọng sẽ mở ra một giai đoạn phát triển mới cho Chi hội Quảng cáo Thủ đô – chuyên nghiệp hơn, gắn kết hơn và chủ động thích ứng với những thay đổi nhanh chóng của ngành quảng cáo trong kỷ nguyên số.</p>                                    </div>\n                                    <div class="sc-empty-layer"></div>\n                                </article>'},{id:"article-5",url:"https://tantienthanh.vn/le-ra-mat-chi-hoi-quang-cao-thu-do-ha-noi/",title:"Lễ ra mắt chi hội quảng cáo thủ đô Hà Nội-Hiệp hội quảng cáo Việt Nam",image:"https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-thu-do-3t-tantienthanh.jpg",description:"Lễ ra mắt chi hội quảng cáo thủ Đô Hà Nội đánh dấu bước ngoặt lớn trong ngành quảng cáo góp phần xây dựng Hiệp hội quảng cáo Việt Nam vươn xa ra thế giới",content:'<div class="entry-content single-page"><div class="lwptoc lwptoc-autoWidth lwptoc-baseItems lwptoc-light lwptoc-notInherit" data-smooth-scroll="1" data-smooth-scroll-offset="24"><div class="lwptoc_i"><div class="lwptoc_header">\n<b class="lwptoc_title">Mục lục bài viết</b>                    <span class="lwptoc_toggle">\n<a href="#" class="lwptoc_toggle_label" data-label="show">hide</a>\n</span></div><div class="lwptoc_items lwptoc_items-visible"><div class="lwptoc_itemWrap"><div class="lwptoc_item">    <a href="#Le_ra_mat_Chi_hoi_quang_cao_Thu_do_dien_ra_thanh_cong_tot_dep">\n<span class="lwptoc_item_number">1</span>\n<span class="lwptoc_item_label">Lễ ra mắt Chi hội quảng cáo Thủ đô diễn ra thành công tốt đẹp.</span>\n</a><div class="lwptoc_itemWrap"><div class="lwptoc_item">    <a href="#Ba_Tran_Thi_Thanh_Tra_-_Tan_Chu_tich_Chi_hoi_Quang_cao_Thu_do_Ha_Noi">\n<span class="lwptoc_item_number">1.1</span>\n<span class="lwptoc_item_label">(Bà Trần Thị Thanh Trà – Tân Chủ tịch Chi hội Quảng cáo Thủ đô Hà Nội)</span>\n</a></div><div class="lwptoc_item">    <a href="#Ban_lanh_dao_cung_cac_hoi_vien_Chi_hoi_Quang_cao_Thu_do_chup_anh_luu_niem">\n<span class="lwptoc_item_number">1.2</span>\n<span class="lwptoc_item_label">(Ban lãnh đạo cùng các hội viên Chi hội Quảng cáo Thủ đô chụp ảnh lưu niệm)</span>\n</a></div><div class="lwptoc_item">    <a href="#Ban_lanh_dao_va_cac_hoi_vien_Chi_hoi_Quang_cao_Thu_do">\n<span class="lwptoc_item_number">1.3</span>\n<span class="lwptoc_item_label">(Ban lãnh đạo và các hội viên Chi hội Quảng cáo Thủ đô)</span>\n</a><div class="lwptoc_itemWrap"><div class="lwptoc_item">    <a href="#Cong_ty_Tan_Tien_Thanh_tu_hao_la_Hoi_vien_Chi_Hoi_quang_cao_thu_do_va_dong_hanh_cung_Chi_hoi_Quang_cao_thu_do_Ha_Noi_Viet_Nam">\n<span class="lwptoc_item_number">1.3.1</span>\n<span class="lwptoc_item_label">Công ty Tân Tiến Thành tự hào là Hội viên Chi Hội quảng cáo thủ đô và đồng hành cùng Chi hội Quảng cáo thủ đô Hà Nội Việt Nam.</span>\n</a></div></div></div></div></div></div></div></div></div><h2><span id="Le_ra_mat_Chi_hoi_quang_cao_Thu_do_dien_ra_thanh_cong_tot_dep"><span style="font-family: \'times new roman\', times, serif; font-size: 105%;">Lễ ra mắt Chi hội quảng cáo Thủ đô diễn ra thành công tốt đẹp.</span></span></h2><p><span style="font-family: \'times new roman\', times, serif; font-size: 105%;">Chiều ngày 10/12/2022 tại Trung tâm hội nghị Quốc gia (Hà Nội) đã diễn ra buổi Lễ ra mắt Chi hội Quảng cáo Thủ đô – trực thuộc Hiệp hội Quảng cáo Việt Nam (VAA). Sự kiện đã đặt dấu mốc quan trọng cho thấy sự phát triển của ngành Quảng cáo nước ta hiện nay ngày càng sôi động. Với mục đích tập hợp, đoàn kết hội viên, hỗ trợ nhau hoạt động, sản xuất có hiệu quả nhằm thúc đẩy ngành quảng cáo Việt Nam phát triển, hội nhập với ngành quảng cáo thế giới, góp phần vào việc phát triển kinh tế – xã hội của đất nước.</span></p><p><span style="font-family: \'times new roman\', times, serif; font-size: 105%;">Đến tham dự buổi lễ ra mắt có ông Lê Quang Tự Do – Cục trưởng cục Phát thanh, Truyền hình và Thông tin Điện tử Bộ Thông tin và Truyền thông; ông Lương Đức Thắng – Phó Cục trưởng Cục văn hóa cơ sở Bộ Văn hóa Thể thao và Du lịch; ông Nguyễn Trường Sơn – Chủ tịch Hiệp Hội Quảng Cáo Việt Nam; ông Đặng Đức Hưng – Chánh Thanh tra, Sở Văn hóa và Thể thao Hà Nội; bà Lê Thị Hồng Hạnh – Trưởng phòng Quản lý văn hóa, Sở văn hóa và Thể thao Hà Nội. Cùng các ông bà Ủy viên BTV, BCH Hiệp hội Quảng cáo Việt Nam. Các cơ quan thông tấn báo chí, truyền hình…</span></p><p><span style="font-family: \'times new roman\', times, serif; font-size: 105%;">Và đặc biệt, chương trình có sự tham dự của hơn 200 doanh nghiệp nằm trong ngành quảng cáo trên cả nước và trong đó có gần 50 doanh nghiệp là hội viên chi hội quảng cáo Thủ đô cùng các vị khách quý đã luôn đồng hành với Hiệp hội trong nhiều năm qua.</span></p><p><img data-lazyloaded="1" src="https://tantienthanh.vn/wp-content/uploads/2022/12/tan-tien-thanh-3t-bond-600x400.jpg" class="size-medium wp-image-4027 aligncenter" data-src="https://tantienthanh.vn/wp-content/uploads/2022/12/tan-tien-thanh-3t-bond-600x400.jpg" alt="chủ tịch hội quảng cáo thủ đô hà nội" width="600" height="400" data-srcset="https://tantienthanh.vn/wp-content/uploads/2022/12/tan-tien-thanh-3t-bond-600x400.jpg 600w, https://tantienthanh.vn/wp-content/uploads/2022/12/tan-tien-thanh-3t-bond-1199x800.jpg 1199w, https://tantienthanh.vn/wp-content/uploads/2022/12/tan-tien-thanh-3t-bond-768x512.jpg 768w, https://tantienthanh.vn/wp-content/uploads/2022/12/tan-tien-thanh-3t-bond-1536x1025.jpg 1536w, https://tantienthanh.vn/wp-content/uploads/2022/12/tan-tien-thanh-3t-bond-300x200.jpg 300w, https://tantienthanh.vn/wp-content/uploads/2022/12/tan-tien-thanh-3t-bond.jpg 1952w" data-sizes="(max-width: 600px) 100vw, 600px"></p><h3 style="text-align: center;"><span id="Ba_Tran_Thi_Thanh_Tra_-_Tan_Chu_tich_Chi_hoi_Quang_cao_Thu_do_Ha_Noi"><span style="font-size: 95%;"><em><span style="font-family: \'times new roman\', times, serif;">(Bà Trần Thị Thanh Trà – Tân Chủ tịch Chi hội Quảng cáo Thủ đô Hà Nội)</span></em></span></span></h3><p>&nbsp;</p><p><span style="font-family: \'times new roman\', times, serif; font-size: 105%;">Phát biểu tại buổi lễ, ông Nguyễn Trường Sơn – Chủ tịch Hiệp hội Quảng Cáo Việt Nam bày tỏ và mong rằng: Việc thành lập Chi hội Quảng cáo Thủ đô là một trong những chiến lược quan trọng của Hiệp hội Quảng Cáo Việt Nam. Sự ra đời của Chi hội Quảng cáo Thủ đô là tất yếu trong điều kiện thị trường quảng cáo phát triển như hiện nay.  Hi vọng Chi hội sẽ là nơi tập hợp những gương mặt đại diện cho các doanh nghiệp hoạt động trên lĩnh vực quảng cáo luôn “Đoàn kết – Hợp tác – Phát triển”. Và VAA được kỳ vọng sẽ tạo nên những dấu ấn quan trọng, để góp phần khẳng định vị thế của ngành Quảng cáo Việt Nam trên trường quốc tế.</span></p><p>&nbsp;</p><p><span style="font-size: 95%;"><img data-lazyloaded="1" src="https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-ha-noi-3t-tan-tien-thanh-622x400.jpg" class="size-medium wp-image-4025 aligncenter" data-src="https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-ha-noi-3t-tan-tien-thanh-622x400.jpg" alt="hội viên hội quảng cáo thủ đô hà nội" width="622" height="400" data-srcset="https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-ha-noi-3t-tan-tien-thanh-622x400.jpg 622w, https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-ha-noi-3t-tan-tien-thanh-1245x800.jpg 1245w, https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-ha-noi-3t-tan-tien-thanh-768x494.jpg 768w, https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-ha-noi-3t-tan-tien-thanh-1536x987.jpg 1536w, https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-ha-noi-3t-tan-tien-thanh-300x193.jpg 300w, https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-ha-noi-3t-tan-tien-thanh-600x386.jpg 600w, https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-ha-noi-3t-tan-tien-thanh.jpg 2048w" data-sizes="(max-width: 622px) 100vw, 622px"></span></p><h3 style="text-align: center;"><span id="Ban_lanh_dao_cung_cac_hoi_vien_Chi_hoi_Quang_cao_Thu_do_chup_anh_luu_niem"><span style="font-size: 95%;"><em><span style="font-family: \'times new roman\', times, serif; color: #555555; text-align: center;">(Ban lãnh đạo cùng các hội viên Chi hội Quảng cáo Thủ đô chụp ảnh lưu niệm)</span></em></span></span></h3><p>&nbsp;</p><p><span style="font-family: \'times new roman\', times, serif; font-size: 105%;">Phát biểu nhận nhiệm vụ, bà Trần Thị Thanh Trà – Tân Chủ tịch Chi hội Quảng cáo Thủ đô cho biết: “Thay mặt Chi hội xin được gửi lời cảm ơn sự quan tâm, ủng hộ của lãnh đạo Hiệp hội Quảng cáo Việt Nam và xin hứa sẽ cố gắng thực hiện tốt nhiệm vụ đã đề ra của Hiệp hội. Mong rằng sẽ nhận được thật nhiều sự giúp đỡ, chỉ đạo của các cơ quan, ban ngành, Hiệp hội quảng cáo Việt Nam và những chia sẻ góp ý của các Chi hội trong ngành Quảng cáo của cả nước để có thể đưa Chi hội Quảng cáo Thủ đô cùng phát triển mạnh mẽ và đoàn kết”.</span></p><p><img data-lazyloaded="1" src="https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-thu-do-3t-tantienthanh-599x400.jpg" class="size-medium wp-image-4026 aligncenter" data-src="https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-thu-do-3t-tantienthanh-599x400.jpg" alt="ban chấp hành hội quảng cáo thủ đô hà nội" width="599" height="400" data-srcset="https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-thu-do-3t-tantienthanh-599x400.jpg 599w, https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-thu-do-3t-tantienthanh-768x513.jpg 768w, https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-thu-do-3t-tantienthanh-300x200.jpg 300w, https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-thu-do-3t-tantienthanh-600x401.jpg 600w, https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-thu-do-3t-tantienthanh.jpg 1152w" data-sizes="(max-width: 599px) 100vw, 599px"></p><h3 style="text-align: center;"><span id="Ban_lanh_dao_va_cac_hoi_vien_Chi_hoi_Quang_cao_Thu_do"><span style="font-size: 95%;"><em><span style="font-family: \'times new roman\', times, serif;">(Ban lãnh đạo và các hội viên Chi hội Quảng cáo Thủ đô)</span></em></span></span></h3><p>&nbsp;</p><p><span style="font-family: \'times new roman\', times, serif; font-size: 105%;">Chi hội Quảng cáo Thủ Đô được thành lập theo Quyết định số 41/QĐ-BTV, ngày 21 tháng 10 năm 2022 của Hiệp hội Quảng cáo Việt Nam. Chi hội Quảng cáo Thủ đô là tổ chức xã hội – nghề nghiệp tập hợp và đại diện cho công đồng các doanh nghiệp kinh doanh các mặt hàng, sản phẩm, dịch vụ quảng cáo các loại hình khác nhau. Là cơ quan đại diện để thúc đẩy và bảo vệ quyền lợi hợp pháp, chính đáng của các hội viên.</span></p><p><span style="font-family: \'times new roman\', times, serif; font-size: 105%;">Được biết, ngày 16/11/2022 tại Hà Nội, Đại hội thành lập Chi hội Quảng cáo Thủ đô lần thứ I đã diễn ra thành công tốt đẹp. Đại hội đã bầu ra 10 Ủy viên Ban chấp hành. Bà Trần Thị Thanh Trà – Tổng giám đốc Công ty cổ phần Đầu tư và thương mại Táo Đỏ được tín nhiệm bầu làm Chủ tịch Chi hội Quảng cáo Thủ đô khóa 1, nhiệm kỳ 2022-2025.</span></p><h4><span id="Cong_ty_Tan_Tien_Thanh_tu_hao_la_Hoi_vien_Chi_Hoi_quang_cao_thu_do_va_dong_hanh_cung_Chi_hoi_Quang_cao_thu_do_Ha_Noi_Viet_Nam"><strong><span style="font-family: \'times new roman\', times, serif; font-size: 105%;">Công ty Tân Tiến Thành tự hào là Hội viên Chi Hội quảng cáo thủ đô và đồng hành cùng Chi hội Quảng cáo thủ đô Hà Nội Việt Nam.</span></strong></span></h4><div class="blog-share text-center"><div class="is-divider medium"></div><div class="social-icons share-icons share-row relative" ><a href="//www.facebook.com/sharer.php?u=https://tantienthanh.vn/le-ra-mat-chi-hoi-quang-cao-thu-do-ha-noi/" data-label="Facebook" onclick="window.open(this.href,this.title,\'width=500,height=500,top=300px,left=300px\');  return false;" rel="noopener noreferrer nofollow" target="_blank" class="icon button circle is-outline tooltip facebook" title="Share on Facebook"><i class="icon-facebook" ></i></a><a href="mailto:enteryour@addresshere.com?subject=L%E1%BB%85%20ra%20m%E1%BA%AFt%20chi%20h%E1%BB%99i%20qu%E1%BA%A3ng%20c%C3%A1o%20th%E1%BB%A7%20%C4%90%C3%B4%20H%C3%A0%20N%E1%BB%99i&amp;body=Check%20this%20out:%20https://tantienthanh.vn/le-ra-mat-chi-hoi-quang-cao-thu-do-ha-noi/" rel="nofollow" class="icon button circle is-outline tooltip email" title="Email to a Friend"><i class="icon-envelop" ></i></a><a href="//pinterest.com/pin/create/button/?url=https://tantienthanh.vn/le-ra-mat-chi-hoi-quang-cao-thu-do-ha-noi/&amp;media=https://tantienthanh.vn/wp-content/uploads/2022/12/hoi-quang-cao-thu-do-3t-tantienthanh.jpg&amp;description=L%E1%BB%85%20ra%20m%E1%BA%AFt%20chi%20h%E1%BB%99i%20qu%E1%BA%A3ng%20c%C3%A1o%20th%E1%BB%A7%20%C4%90%C3%B4%20H%C3%A0%20N%E1%BB%99i" onclick="window.open(this.href,this.title,\'width=500,height=500,top=300px,left=300px\');  return false;" rel="noopener noreferrer nofollow" target="_blank" class="icon button circle is-outline tooltip pinterest" title="Pin on Pinterest"><i class="icon-pinterest" ></i></a></div></div></div><nav role="navigation" id="nav-below" class="navigation-post"><div class="flex-row next-prev-nav bt bb"><div class="flex-col flex-grow nav-prev text-left"><div class="nav-previous"><a href="https://tantienthanh.vn/chuong-trinh-tu-thien-niem-tin-cho-em/" rel="prev"><span class="hide-for-small"><i class="icon-angle-left" ></i></span> Tân Tiến Thành đồng hành từ thiện Niềm tin cho em</a></div></div><div class="flex-col flex-grow nav-next text-right"><div class="nav-next"><a href="https://tantienthanh.vn/tiec-tat-nien-cong-ty-tan-tien-thanh-don-xuan-2023/" rel="next">Tiệc tất niên công ty Tân Tiến Thành đón xuân 2023 <span class="hide-for-small"><i class="icon-angle-right" ></i></span></a></div></div></div></nav></div>'}];